export const AUMERA_HTML = "<!doctype html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n<meta name=\"robots\" content=\"noindex,nofollow\">\n<title>Aumera Revamp Brief</title>\n<meta name=\"claude:viewport-fit-sides\" content=\"cover\">\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link rel=\"stylesheet\" href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap\">\n<style>\n/* Layout: white, airy brief. A blush \"sunrise\" glow (from the logo's sun) opens the page around the emblem; a slim sticky bar tracks progress; contents rail on the left, one column of soft question cards on the right. Single light theme by design. */\n:root{\n  color-scheme:light;\n  --bg:#FFFFFF;\n  --tint:#FBF7F5;\n  --blush:#F6E8E0;\n  --ink:#2A1E1B;\n  --body:#4A3B36;\n  --muted:#8A7670;\n  --line:#EFE4DE;\n  --line-strong:#E4D3CA;\n  --accent:#A0644C;       /* rose gold */\n  --accent-deep:#6E3A2E;\n  --accent-soft:#F5E9E2;\n  --ok:#5F8466;\n  --f-display:\"Inter\", system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  --f-body:\"Inter\", system-ui, -apple-system, \"Segoe UI\", Roboto, sans-serif;\n  --s1:4px;--s2:8px;--s3:12px;--s4:16px;--s5:24px;--s6:32px;--s7:48px;--s8:64px;--s9:96px;--s10:128px;\n  --shadow:none;--r:2px;\n}\n*{box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{background:var(--bg);color:var(--body);font-family:var(--f-body);font-weight:400;font-size:16px;line-height:1.65;-webkit-font-smoothing:antialiased}\nbody::before{content:\"\";position:fixed;inset:0 0 auto;height:env(safe-area-inset-top,0px);z-index:30;background:rgba(255,255,255,.92)}\n.container{max-width:1160px;margin:0 auto;padding-left:max(20px,env(safe-area-inset-left,0px));padding-right:max(20px,env(safe-area-inset-right,0px))}\n.eyebrow{font-size:11.5px;font-weight:500;letter-spacing:.22em;text-transform:uppercase;color:var(--accent)}\nh1,h2,.ql,.tb-sec,.finish h2{font-variant-numeric:lining-nums}\nsvg.i{width:16px;height:16px;flex:none;stroke:currentColor;fill:none;stroke-width:1.5;stroke-linecap:round;stroke-linejoin:round}\n\n/* Sticky progress bar */\n.topbar{position:sticky;top:env(safe-area-inset-top,0px);z-index:20;background:rgba(255,255,255,.88);backdrop-filter:saturate(1.4) blur(14px);-webkit-backdrop-filter:saturate(1.4) blur(14px);border-bottom:1px solid transparent;transition:border-color .3s}\n.topbar.stuck{border-bottom-color:var(--line)}\n.topbar .container{display:flex;align-items:center;gap:var(--s5);padding-block:12px}\n.topbar img{height:34px;width:auto;opacity:0;transform:translateY(4px);transition:opacity .3s,transform .3s}\n.topbar.stuck img{opacity:1;transform:none}\n.tb-mid{flex:1;display:flex;align-items:center;gap:var(--s4);min-width:0}\n.tb-sec{font-size:13.5px;font-weight:500;color:var(--ink);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;min-width:0;flex:0 1 auto}\n.bar{flex:1 1 120px;height:3px;background:var(--line);border-radius:0;overflow:hidden;position:relative;min-width:80px}\n.bar i{position:absolute;inset:0 auto 0 0;width:0;background:var(--accent);transition:width .6s cubic-bezier(.2,.7,.2,1)}\n.count{font-size:12.5px;color:var(--muted);font-variant-numeric:tabular-nums;white-space:nowrap}\n.save{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--muted);white-space:nowrap}\n.save::before{content:\"\";width:6px;height:6px;border-radius:50%;background:currentColor;opacity:.8}\n.save[data-s=\"saved\"]{color:var(--ok)}\n.save[data-s=\"saving\"]{color:var(--accent)}\n.save[data-s=\"local\"]{color:var(--accent-deep)}\n\n/* Hero */\n.hero{text-align:center;padding-block:var(--s7) var(--s8);border-bottom:1px solid var(--line)}\n.hero .container{display:grid;justify-items:center;gap:var(--s4)}\n.hero .logo{width:132px;height:auto;max-width:100%}\n.hero h1{font-family:var(--f-display);font-weight:600;font-size:clamp(36px,5.2vw,60px);line-height:1.05;letter-spacing:-.035em;color:var(--ink);margin:var(--s2) 0 0;max-width:18ch;text-wrap:balance}\n.hero h1 em{font-style:normal;color:var(--accent)}\n.hero p{max-width:60ch;font-size:16px;color:var(--body);margin:0;text-wrap:pretty}\n.meta{display:flex;flex-wrap:wrap;justify-content:center;gap:var(--s2) var(--s5);font-size:13px;color:var(--muted);margin-top:var(--s1)}\n@keyframes rise{from{opacity:.001;transform:translateY(10px)}to{opacity:1;transform:none}}\n\n/* Main grid */\n.grid{display:grid;grid-template-columns:250px minmax(0,1fr);gap:var(--s9);padding-block:var(--s8) var(--s9)}\nnav.index{position:sticky;top:calc(env(safe-area-inset-top,0px) + 84px);align-self:start;display:grid;gap:2px}\nnav.index .lbl{margin:0 0 var(--s3) 12px}\nnav.index a{display:flex;align-items:center;gap:12px;padding:9px 12px;border-radius:var(--r);color:var(--muted);text-decoration:none;font-size:14.5px;line-height:1.3;transition:background .2s,color .2s}\nnav.index a:hover{color:var(--ink);background:var(--tint)}\nnav.index a.on{color:var(--ink);background:var(--accent-soft)}\nnav.index a .t{flex:1;min-width:0}\n.ring{width:20px;height:20px;flex:none}\n.ring circle{fill:none;stroke-width:2}\n.ring .bg{stroke:var(--line-strong)}\n.ring .fg{stroke:var(--accent);stroke-linecap:round;transform:rotate(-90deg);transform-origin:50% 50%;transition:stroke-dashoffset .5s}\nnav.index a.done .ring .fg{stroke:var(--ok)}\n.ring .tick{stroke:var(--ok);stroke-width:1.8;fill:none;opacity:0;transition:opacity .3s}\nnav.index a.done .ring .tick{opacity:1}\n\nmain{max-width:760px;min-width:0}\nsection.sec{scroll-margin-top:90px;padding-top:var(--s2)}\nsection.sec + section.sec{margin-top:var(--s10)}\n.sec-head{display:grid;grid-template-columns:auto minmax(0,1fr);gap:var(--s2) var(--s5);align-items:end;margin-bottom:var(--s6)}\n.sec-num{font-weight:500;font-size:13px;letter-spacing:.12em;line-height:1;color:var(--accent);font-variant-numeric:tabular-nums;grid-column:1/-1}\n.sec-head h2{font-family:var(--f-display);font-weight:600;font-size:clamp(28px,3.4vw,38px);line-height:1.1;letter-spacing:-.03em;grid-column:1/-1;color:var(--ink);margin:0;text-wrap:balance}\n.sec-head p{grid-column:1/-1;margin:var(--s2) 0 0;color:var(--muted);max-width:60ch}\n\n.cards{display:grid;gap:var(--s4)}\n.card{position:relative;background:var(--bg);border:1px solid var(--line);border-radius:var(--r);padding:28px 30px;box-shadow:var(--shadow);transition:border-color .3s,box-shadow .3s}\n.card:focus-within{border-color:var(--ink)}\n.qtop{display:flex;align-items:center;justify-content:space-between;gap:var(--s3);margin-bottom:var(--s3)}\n.qn{font-size:11.5px;font-weight:500;letter-spacing:.14em;color:var(--muted);font-variant-numeric:tabular-nums}\n.badge{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:var(--ok);opacity:0;transform:scale(.9);transition:opacity .3s,transform .3s}\n.card.answered .badge{opacity:1;transform:none}\n.ql{font-weight:500;font-size:17px;letter-spacing:-.01em;line-height:1.45;color:var(--ink);margin:0 0 var(--s2);text-wrap:pretty}\n.card.confirm .ql{font-weight:500;font-size:21px;line-height:1.4;letter-spacing:-.02em}\n.qh{font-size:14.5px;color:var(--muted);margin:0 0 var(--s4)}\n.found{display:flex;gap:10px;align-items:flex-start;font-size:14px;line-height:1.5;color:var(--body);background:var(--tint);border-left:2px solid var(--accent);border-radius:0;padding:10px 14px;margin:var(--s2) 0 var(--s4)}\n.found svg{color:var(--accent);margin-top:2px}\n.found b{display:block;font-size:10.5px;font-weight:500;letter-spacing:.18em;text-transform:uppercase;color:var(--accent);margin-bottom:1px}\n.qbody{margin-top:var(--s4)}\n\ninput[type=text],textarea{width:100%;font:inherit;font-size:15.5px;color:var(--ink);background:var(--tint);border:1px solid var(--line);border-radius:var(--r);padding:13px 16px;transition:border-color .2s,background .2s,box-shadow .2s}\ntextarea{min-height:110px;resize:vertical;line-height:1.6}\ninput[type=text]:hover,textarea:hover{border-color:var(--line-strong)}\ninput[type=text]:focus,textarea:focus{outline:none;background:var(--bg);border-color:var(--ink);box-shadow:none}\n::placeholder{color:#B3A39D}\n\n.chips{display:flex;flex-wrap:wrap;gap:10px}\n.chip{display:inline-flex;align-items:center;gap:8px;font:inherit;font-size:14.5px;color:var(--body);background:var(--bg);border:1px solid var(--line-strong);border-radius:var(--r);padding:9px 16px;cursor:pointer;transition:background .2s,color .2s,border-color .2s,transform .15s}\n.chip:hover{border-color:var(--accent);color:var(--accent-deep)}\n.chip:active{transform:none}\n.chip svg{width:14px;height:14px;display:none}\n.chip[aria-pressed=\"true\"]{background:var(--ink);border-color:var(--ink);color:#FFFFFF}\n.chip[aria-pressed=\"true\"] svg{display:block}\n.seg .chip{padding:10px 20px}\n.seg .chip svg{display:block;opacity:.55}\n.seg .chip[aria-pressed=\"true\"] svg{opacity:1}\n.chip:focus-visible,.drop:focus-visible,.btn:focus-visible,.addnote:focus-visible,nav.index a:focus-visible{outline:2px solid var(--accent);outline-offset:3px}\n\n.addnote{display:inline-flex;align-items:center;gap:6px;margin-top:var(--s4);font:inherit;font-size:13.5px;color:var(--accent);background:none;border:0;padding:2px 0;cursor:pointer}\n.addnote:hover{color:var(--accent-deep);text-decoration:underline;text-underline-offset:3px}\n.notewrap{margin-top:var(--s3)}\n\n.drop{display:flex;align-items:center;gap:var(--s4);border:1px dashed var(--line-strong);border-radius:var(--r);padding:20px 22px;background:var(--tint);cursor:pointer;transition:border-color .2s,background .2s}\n.drop:hover,.drop.over{border-color:var(--accent);background:var(--accent-soft)}\n.drop .ic{display:grid;place-items:center;width:44px;height:44px;border-radius:var(--r);background:var(--bg);border:1px solid var(--line);color:var(--accent);flex:none}\n.drop .ic svg{width:20px;height:20px}\n.drop strong{display:block;color:var(--ink);font-weight:500;font-size:15px}\n.drop span.dmsg{font-size:13px;color:var(--muted)}\n.drop[aria-disabled=\"true\"]{cursor:default}\n.files{display:grid;grid-template-columns:repeat(auto-fill,minmax(112px,1fr));gap:10px;margin-top:var(--s3)}\n.files:empty{display:none}\n.file{border:1px solid var(--line);border-radius:var(--r);overflow:hidden;background:var(--bg);font-size:12px}\n.file .th{aspect-ratio:1;max-width:100%;display:grid;place-items:center;background:var(--tint);color:var(--muted);font-size:12px;letter-spacing:.1em}\n.file .th img{width:100%;height:100%;object-fit:cover;display:block}\n.file .nm{padding:6px 9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:var(--body)}\n.file.up .th{animation:pulse 1.2s ease-in-out infinite}\n@keyframes pulse{50%{opacity:.5}}\n.link-in{margin-top:var(--s3)}\n\n.btn{display:inline-flex;align-items:center;gap:10px;font:inherit;font-weight:500;font-size:15px;letter-spacing:.02em;background:var(--ink);color:#FFFFFF;border:0;border-radius:var(--r);padding:14px 28px;cursor:pointer;text-decoration:none;transition:transform .2s,background .2s}\n.btn:hover{background:var(--accent-deep)}\n.btn:disabled{opacity:.6;cursor:default;transform:none}\n\n.finish{margin-top:var(--s10);display:grid;gap:var(--s4);justify-items:center;text-align:center;padding:var(--s8) var(--s5);border-radius:var(--r);background:var(--tint);border:1px solid var(--line)}\n.finish img{width:84px;height:auto}\n.finish h2{font-family:var(--f-display);font-weight:600;letter-spacing:-.03em;font-size:clamp(28px,3.6vw,36px);color:var(--ink);margin:0;line-height:1.1;text-wrap:balance}\n.finish p{margin:0;color:var(--muted);max-width:50ch}\n.note{font-size:14px;color:var(--muted);min-height:1.5em}\n\nfooter{border-top:1px solid var(--line)}\nfooter .container{display:flex;justify-content:space-between;gap:var(--s4);flex-wrap:wrap;padding-block:var(--s5);font-size:13px;color:var(--muted)}\nfooter em{font-style:normal;color:var(--accent)}\n\n@media (max-width:960px){\n  .grid{grid-template-columns:minmax(0,1fr);gap:var(--s6)}\n  nav.index{display:none}\n  main{max-width:none}\n}\n@media (max-width:560px){\n  .hero{padding-block:var(--s6) var(--s7)}\n  .hero .logo{width:112px}\n  .hero p{font-size:16px}\n  .topbar img{display:none}\n  .count{display:none}\n  .card{padding:22px 20px}\n  .card.confirm .ql{font-size:19px}\n  section.sec + section.sec{margin-top:var(--s9)}\n  .drop{padding:16px}\n}\n@media (prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{transition:none!important;animation:none!important}}\n</style>\n<style>body{margin:0}img{max-width:100%}[hidden]{display:none!important}</style>\n</head>\n<body>\n\n\n<div class=\"topbar\" id=\"topbar\">\n  <div class=\"container\">\n    <img id=\"tbLogo\" alt=\"Aumèra\" width=\"33\" height=\"34\">\n    <div class=\"tb-mid\">\n      <span class=\"tb-sec\" id=\"tbSec\">Getting to know you</span>\n      <div class=\"bar\" aria-hidden=\"true\"><i id=\"barFill\"></i></div>\n      <span class=\"count\" id=\"countAll\">0 of 0</span>\n    </div>\n    <span class=\"save\" id=\"saveState\" data-s=\"idle\">Connecting</span>\n  </div>\n</div>\n\n<header class=\"hero\">\n  <div class=\"container\">\n    <img class=\"logo\" id=\"heroLogo\" src=\"data:image/png;base64,\" alt=\"Aumèra, awaken the infinite within\" width=\"132\" height=\"135\">\n    <span class=\"eyebrow\">Website revamp · Getting to know you</span>\n    <h1>Let’s make sure we <em>understood</em> Aumèra right.</h1>\n    <p>Here is what we’ve learned from our conversation and your current website. Confirm or correct it, and share the details and photos the new site will need. Skip anything you’re unsure about.</p>\n    <div class=\"meta\"><span>About 15 minutes</span><span>Saves as you go</span></div>\n  </div>\n</header>\n\n<div class=\"container\">\n  <div class=\"grid\">\n    <nav class=\"index\" id=\"index\" aria-label=\"Sections\"><span class=\"eyebrow lbl\">Contents</span></nav>\n    <main id=\"form\"></main>\n  </div>\n</div>\n\n<footer>\n  <div class=\"container\">\n    <span>Notes marked “What we noted” come from our call and from aumera.co.in.</span>\n    <em>awaken the infinite within</em>\n  </div>\n</footer>\n\n<!--BRIEF_SCRIPT-->\n\n</body>\n</html>\n";

export const AUMERA_SCRIPT = "\n/* Aumera brief page, wired to Sales CRM: questions and saved answers come from window.__BRIEF__,\n   each section is PUT to the public brief API, files go to storage through signed upload URLs. */\nconst BRIEF = window.__BRIEF__;\nconst API = \"/api/v1/briefs/publico/\" + BRIEF.token;\nconst YES=[\"Yes, that’s right\",\"Partly\",\"Not quite\"];\nconst SECTIONS = BRIEF.secoes;\n\n/* ---------- icons ---------- */\nconst ICON={\n  check:'<path d=\"M3 8.5l3 3 7-7\"/>',\n  partly:'<path d=\"M3.5 8h9\"/>',\n  no:'<path d=\"M4.5 4.5l7 7M11.5 4.5l-7 7\"/>',\n  sun:'<circle cx=\"8\" cy=\"9\" r=\"2.6\"/><path d=\"M8 2.5v1.6M3.4 4.4l1.1 1.1M12.6 4.4l-1.1 1.1M1.8 9h1.6M12.6 9h1.6M2 13.5h12\"/>',\n  up:'<path d=\"M10 13V4M6 8l4-4 4 4M4 16h12\"/>',\n  plus:'<path d=\"M8 3.5v9M3.5 8h9\"/>'\n};\nconst svg=(name,vb=\"0 0 16 16\")=>{const s=document.createElementNS(\"http://www.w3.org/2000/svg\",\"svg\");s.setAttribute(\"viewBox\",vb);s.setAttribute(\"class\",\"i\");s.setAttribute(\"aria-hidden\",\"true\");s.innerHTML=ICON[name];return s;};\n\n/* ---------- state ---------- */\nconst S = {};\nSECTIONS.forEach(s=>{const r=BRIEF.respostas[s.id]; S[s.id]={v:Object.assign({},(r&&r.v)||{}),files:JSON.parse(JSON.stringify((r&&r.files)||{}))};});\nconst LS=\"brief-\"+BRIEF.token;\n/* Answers typed while offline survive in this browser; the server copy wins when it is newer. */\ntry{const d=JSON.parse(localStorage.getItem(LS)||\"null\"); if(d) for(const k in d) if(S[k]&&!BRIEF.respostas[k]) S[k]=d[k];}catch(e){}\n\nconst $=s=>document.querySelector(s);\nconst el=(t,a={},...c)=>{const e=document.createElement(t);for(const k in a){if(k===\"class\")e.className=a[k];else if(k===\"text\")e.textContent=a[k];else if(k.startsWith(\"on\"))e.addEventListener(k.slice(2),a[k]);else e.setAttribute(k,a[k]);}c.flat().forEach(x=>x!=null&&e.append(x));return e;};\nconst optsOf=q=>q.type===\"confirm\"?YES:q.opts;\nconst RING_C=2*Math.PI*8;\nconst fileUrl=f=>API+\"/arquivo?path=\"+encodeURIComponent(f.path);\n\n/* ---------- render ---------- */\nfunction render(){\n  const form=$(\"#form\"), idx=$(\"#index\");\n  SECTIONS.forEach((s,si)=>{\n    const n=String(si+1).padStart(2,\"0\");\n    const ring=document.createElementNS(\"http://www.w3.org/2000/svg\",\"svg\");\n    ring.setAttribute(\"viewBox\",\"0 0 20 20\"); ring.setAttribute(\"class\",\"ring\"); ring.setAttribute(\"aria-hidden\",\"true\");\n    ring.innerHTML=`<circle class=\"bg\" cx=\"10\" cy=\"10\" r=\"8\"/><circle class=\"fg\" cx=\"10\" cy=\"10\" r=\"8\" stroke-dasharray=\"${RING_C}\" stroke-dashoffset=\"${RING_C}\"/><path class=\"tick\" d=\"M6.5 10.2l2.3 2.3 4.7-4.8\"/>`;\n    idx.append(el(\"a\",{href:\"#\"+s.id,id:\"nav-\"+s.id},ring,el(\"span\",{class:\"t\",text:s.t})));\n    const sec=el(\"section\",{class:\"sec\",id:s.id,\"data-title\":s.t},\n      el(\"div\",{class:\"sec-head\"},el(\"span\",{class:\"sec-num\",\"aria-hidden\":\"true\",text:n}),el(\"h2\",{text:s.t}),s.d?el(\"p\",{text:s.d}):null));\n    const cards=el(\"div\",{class:\"cards\"});\n    s.q.forEach((q,qi)=>cards.append(renderQ(s,q,`${si+1}.${qi+1}`)));\n    sec.append(cards); form.append(sec);\n  });\n  const fin=el(\"div\",{class:\"finish\",id:\"finish\"},\n    el(\"img\",{alt:\"\",width:\"84\",height:\"86\",id:\"finLogo\"}),\n    el(\"h2\",{text:\"That’s everything we need to begin.\"}),\n    el(\"p\",{text:\"Your answers are already saved. Let us know you’re done, and you can still come back and edit anything later.\"}),\n    el(\"button\",{class:\"btn\",id:\"doneBtn\",type:\"button\",onclick:markDone},\"I’m done for now\",svg(\"check\")),\n    el(\"span\",{class:\"note\",id:\"doneNote\",role:\"status\"}));\n  form.append(fin);\n  const src=$(\"#heroLogo\").src; $(\"#tbLogo\").src=src; $(\"#finLogo\").src=src;\n  refreshAll();\n}\n\nfunction noteBlock(s,q,key,placeholder,open){\n  const wrap=el(\"div\",{class:\"notewrap\",id:\"nw-\"+key});\n  const inp=el(\"input\",{type:\"text\",id:\"o-\"+key,\"aria-label\":\"Note for: \"+q.q,placeholder,value:S[s.id].v[q.id+\"__note\"]||\"\",oninput:e=>setV(s.id,q.id+\"__note\",e.target.value)});\n  wrap.append(inp);\n  const btn=el(\"button\",{type:\"button\",class:\"addnote\",id:\"an-\"+key,onclick:()=>{wrap.hidden=false;btn.hidden=true;inp.focus();}},svg(\"plus\"),\"Add a note\");\n  wrap.hidden=!open; btn.hidden=open;\n  return [btn,wrap];\n}\n\nfunction renderQ(s,q,num){\n  const key=s.id+\".\"+q.id, val=S[s.id].v[q.id];\n  const card=el(\"div\",{class:\"card\"+(q.type===\"confirm\"&&!q.found?\" confirm\":\"\"),id:\"w-\"+key});\n  card.append(el(\"div\",{class:\"qtop\"},el(\"span\",{class:\"qn\",text:num}),el(\"span\",{class:\"badge\"},svg(\"check\"),\"Answered\")));\n  card.append(el(\"p\",{class:\"ql\",id:\"l-\"+key,text:q.q}));\n  if(q.hint) card.append(el(\"p\",{class:\"qh\",text:q.hint}));\n  if(q.found) card.append(el(\"div\",{class:\"found\"},svg(\"sun\"),el(\"div\",{},el(\"b\",{text:\"What we noted\"}),el(\"span\",{text:q.found}))));\n  const body=el(\"div\",{class:\"qbody\"});\n  if(q.type===\"text\"){\n    body.append(el(\"input\",{type:\"text\",id:\"q-\"+key,\"aria-labelledby\":\"l-\"+key,value:val||\"\",placeholder:\"Type here\",oninput:e=>setV(s.id,q.id,e.target.value)}));\n  } else if(q.type===\"long\"){\n    const t=el(\"textarea\",{id:\"q-\"+key,\"aria-labelledby\":\"l-\"+key,placeholder:\"Type here\",oninput:e=>setV(s.id,q.id,e.target.value)}); t.value=val||\"\"; body.append(t);\n  } else if(q.type===\"one\"||q.type===\"many\"||q.type===\"confirm\"){\n    const box=el(\"div\",{class:\"chips\"+(q.type===\"confirm\"?\" seg\":\"\"),role:\"group\",\"aria-labelledby\":\"l-\"+key,id:\"q-\"+key});\n    optsOf(q).forEach((o,i)=>{\n      const ic=q.type===\"confirm\"?svg([\"check\",\"partly\",\"no\"][i]):svg(\"check\");\n      box.append(el(\"button\",{type:\"button\",class:\"chip\",\"data-o\":o,\"aria-pressed\":\"false\",onclick:()=>toggle(s.id,q,o)},ic,o));\n    });\n    body.append(box);\n    const hasNote=!!(S[s.id].v[q.id+\"__note\"]||\"\").trim();\n    body.append(...noteBlock(s,q,key,q.type===\"confirm\"?\"What should we correct or add?\":\"Something else, or a note\",hasNote));\n    queueMicrotask(()=>paintChips(s.id,q));\n  } else if(q.type===\"file\"){\n    const inp=el(\"input\",{type:\"file\",multiple:\"\",hidden:\"\",id:\"f-\"+key,onchange:e=>{upload(s.id,q.id,[...e.target.files]);e.target.value=\"\";}});\n    const drop=el(\"div\",{class:\"drop\",id:\"d-\"+key,tabindex:\"0\",role:\"button\",\"aria-labelledby\":\"l-\"+key,\n      onclick:()=>inp.click(),\n      onkeydown:e=>{if(e.key===\"Enter\"||e.key===\" \"){e.preventDefault();inp.click();}},\n      ondragover:e=>{e.preventDefault();drop.classList.add(\"over\");},\n      ondragleave:()=>drop.classList.remove(\"over\"),\n      ondrop:e=>{e.preventDefault();drop.classList.remove(\"over\");upload(s.id,q.id,[...e.dataTransfer.files]);}},\n      el(\"span\",{class:\"ic\"},svg(\"up\",\"0 0 20 20\")),\n      el(\"div\",{},el(\"strong\",{text:\"Drop files here or click to upload\"}),el(\"span\",{class:\"dmsg\",text:\"Images, PDFs or videos, up to 20 MB each\"})));\n    body.append(inp,drop,el(\"div\",{class:\"files\",id:\"fl-\"+key}));\n    body.append(el(\"input\",{type:\"text\",class:\"link-in\",id:\"lk-\"+key,\"aria-label\":\"Link for: \"+q.q,placeholder:\"Or paste a Google Drive / Dropbox link\",value:S[s.id].v[q.id+\"__link\"]||\"\",oninput:e=>setV(s.id,q.id+\"__link\",e.target.value)}));\n    queueMicrotask(()=>paintFiles(s.id,q.id));\n  }\n  card.append(body);\n  return card;\n}\n\nfunction openNote(sid,qid){\n  const key=sid+\".\"+qid, w=document.getElementById(\"nw-\"+key), b=document.getElementById(\"an-\"+key);\n  if(w&&w.hidden){w.hidden=false; if(b) b.hidden=true;}\n}\nfunction paintChips(sid,q){\n  const key=sid+\".\"+q.id, v=S[sid].v[q.id]; const sel=Array.isArray(v)?v:(v?[v]:[]);\n  document.querySelectorAll(`#q-${CSS.escape(key)} .chip`).forEach(b=>b.setAttribute(\"aria-pressed\",sel.includes(b.dataset.o)?\"true\":\"false\"));\n}\nfunction paintFiles(sid,qid){\n  const box=document.getElementById(\"fl-\"+sid+\".\"+qid); if(!box) return;\n  box.replaceChildren(...(S[sid].files[qid]||[]).map(f=>{\n    const isImg=(f.type||\"\").startsWith(\"image/\");\n    const th=el(\"div\",{class:\"th\"}, isImg&&f.path ? el(\"img\",{src:fileUrl(f),alt:f.name,loading:\"lazy\"}) : el(\"span\",{text:(f.name.split(\".\").pop()||\"file\").toUpperCase().slice(0,4)}));\n    const item=el(\"div\",{class:\"file\"+(f.pending?\" up\":\"\")},th,el(\"div\",{class:\"nm\",title:f.name,text:f.name}));\n    if(f.path) item.addEventListener(\"click\",()=>window.open(fileUrl(f),\"_blank\",\"noopener\"));\n    return item;\n  }));\n}\n\nfunction isAnswered(sid,q){\n  const v=S[sid].v;\n  if(q.type===\"file\") return (S[sid].files[q.id]||[]).some(f=>!f.pending) || !!(v[q.id+\"__link\"]||\"\").trim();\n  const a=v[q.id]; const note=(v[q.id+\"__note\"]||\"\").trim();\n  return (Array.isArray(a)?a.length>0:!!(a&&String(a).trim())) || !!note;\n}\nfunction refreshAll(){\n  let tot=0, done=0;\n  SECTIONS.forEach(s=>{\n    let d=0; s.q.forEach(q=>{const a=isAnswered(s.id,q); if(a)d++; const w=document.getElementById(\"w-\"+s.id+\".\"+q.id); w&&w.classList.toggle(\"answered\",a);});\n    tot+=s.q.length; done+=d;\n    const n=document.getElementById(\"nav-\"+s.id);\n    if(n){ n.classList.toggle(\"done\",d===s.q.length); const fg=n.querySelector(\".fg\"); fg&&fg.setAttribute(\"stroke-dashoffset\",String(RING_C*(1-(s.q.length?d/s.q.length:0)))); n.setAttribute(\"aria-label\",`${s.t}, ${d} of ${s.q.length} answered`); }\n  });\n  $(\"#barFill\").style.width=(tot?done/tot*100:0)+\"%\";\n  $(\"#countAll\").textContent=`${done} of ${tot}`;\n}\n\n/* ---------- edits ---------- */\nfunction setV(sid,k,val){S[sid].v[k]=val; changed(sid);}\nfunction toggle(sid,q,o){\n  const v=S[sid].v;\n  if(q.type===\"many\"){const a=Array.isArray(v[q.id])?[...v[q.id]]:[]; const i=a.indexOf(o); i>=0?a.splice(i,1):a.push(o); v[q.id]=a;}\n  else v[q.id]= v[q.id]===o ? \"\" : o;\n  paintChips(sid,q);\n  if(q.type===\"confirm\"&&(v[q.id]===\"Partly\"||v[q.id]===\"Not quite\")) openNote(sid,q.id);\n  changed(sid);\n}\n\n/* ---------- saving ---------- */\nconst timers={}, chains={}, dirty=new Set();\nfunction setSave(s,t){const e=$(\"#saveState\"); e.dataset.s=s; e.textContent=t;}\nfunction changed(sid){\n  refreshAll();\n  try{localStorage.setItem(LS,JSON.stringify(S));}catch(e){}\n  dirty.add(sid); setSave(\"saving\",\"Saving\");\n  clearTimeout(timers[sid]); timers[sid]=setTimeout(()=>flush(sid),800);\n}\nfunction clean(sid){const f={};for(const k in S[sid].files)f[k]=S[sid].files[k].filter(x=>!x.pending).map(({path,name,type,size})=>({path,name,type:type||\"\",size:size||0}));return {v:S[sid].v,files:f};}\nfunction flush(sid){\n  chains[sid]=(chains[sid]||Promise.resolve()).then(async()=>{\n    dirty.delete(sid);\n    try{\n      const r=await fetch(API+\"/secoes/\"+encodeURIComponent(sid),{method:\"PUT\",headers:{\"content-type\":\"application/json\"},body:JSON.stringify(clean(sid))});\n      if(!r.ok) throw new Error(String(r.status));\n      if(!dirty.size) setSave(\"saved\",\"Saved\");\n    }\n    catch(e){ setSave(\"local\",\"Saved on this device\"); }\n  });\n  return chains[sid];\n}\nasync function upload(sid,qid,list){\n  if(!list.length) return;\n  const arr=S[sid].files[qid]=S[sid].files[qid]||[];\n  for(const file of list){\n    if(file.size>20*1024*1024){ setSave(\"local\",`${file.name} is over 20 MB. Add a Google Drive link instead`); continue; }\n    const tmp={path:\"\",name:file.name,type:file.type,size:file.size,pending:true}; arr.push(tmp); paintFiles(sid,qid);\n    try{\n      const r=await fetch(API+\"/upload\",{method:\"POST\",headers:{\"content-type\":\"application/json\"},body:JSON.stringify({secao:sid,pergunta:qid,nome:file.name,tamanho:file.size})});\n      if(!r.ok) throw new Error(String(r.status));\n      const {path,url}=await r.json();\n      const up=await fetch(url,{method:\"PUT\",headers:{\"content-type\":file.type||\"application/octet-stream\",\"x-upsert\":\"false\"},body:file});\n      if(!up.ok) throw new Error(String(up.status));\n      tmp.path=path; delete tmp.pending;\n    }\n    catch(e){ arr.splice(arr.indexOf(tmp),1); setSave(\"local\",`Couldn’t upload ${file.name}. Try a smaller file or add a link`); }\n    paintFiles(sid,qid); changed(sid);\n  }\n}\nasync function markDone(){\n  const b=$(\"#doneBtn\"), n=$(\"#doneNote\");\n  b.disabled=true;\n  // Send anything still waiting first, so \"done\" never races the last answer.\n  const waiting=[...dirty]; waiting.forEach(sid=>{clearTimeout(timers[sid]);}); await Promise.all(waiting.map(flush));\n  try{\n    const r=await fetch(API+\"/concluir\",{method:\"POST\"});\n    if(!r.ok) throw new Error(String(r.status));\n    const d=await r.json(); showSent(d.concluidoEm);\n  }\n  catch(e){ n.textContent=\"That didn’t go through. Please try again in a moment.\"; }\n  b.disabled=false;\n}\nfunction showSent(at){\n  $(\"#doneBtn\").firstChild.textContent=\"Sent \";\n  $(\"#doneNote\").textContent=\"Sent on \"+new Date(at).toLocaleDateString(\"en-IN\",{day:\"numeric\",month:\"long\",year:\"numeric\"})+\". You can still edit anything.\";\n}\n\n/* ---------- start ---------- */\nrender();\nsetSave(\"saved\",\"Saved\");\nif(BRIEF.concluidoEm) showSent(BRIEF.concluidoEm);\n\n/* ---------- scroll UI ---------- */\nconst tb=$(\"#topbar\");\nnew IntersectionObserver(([e])=>tb.classList.toggle(\"stuck\",!e.isIntersecting),{rootMargin:\"-60px 0px 0px 0px\"}).observe($(\"#heroLogo\"));\nconst io=new IntersectionObserver(es=>es.forEach(e=>{ if(e.isIntersecting){\n  document.querySelectorAll(\"nav.index a\").forEach(a=>a.classList.toggle(\"on\",a.getAttribute(\"href\")===\"#\"+e.target.id));\n  $(\"#tbSec\").textContent=e.target.dataset.title;\n}}),{rootMargin:\"-35% 0px -55% 0px\"});\ndocument.querySelectorAll(\"section.sec\").forEach(s=>io.observe(s));\n";
